  function text(parent,value,x,y,w,size=14,weight='regular',color='ink',lines=0){const n=figma.createText();n.name=String(value).replace(/\n/g,' ').slice(0,70);n.fontName=weight==='bold'?bold:weight==='semibold'?semibold:regular;n.fontSize=size;n.lineHeight={unit:'PIXELS',value:Math.ceil(size*1.43)};n.characters=String(value);n.fills=[paint(color)];n.textAutoResize='HEIGHT';n.resize(Math.max(1,w),Math.ceil(size*1.43));if(lines){n.textAutoResize='NONE';n.resize(w,Math.ceil(size*1.43)*lines);n.maxLines=lines;n.textTruncation='ENDING';}parent.appendChild(n);n.x=x;n.y=y;return n;}
  function icon(parent,name,x,y,size=24,color='ink'){const raw=DATA.icons[name]||DATA.icons.book;const n=figma.createNodeFromSvg(raw.replace(/currentColor/g,C[color]||color));n.name='Biểu tượng / '+name;n.resize(size,size);parent.appendChild(n);n.x=x;n.y=y;n.setPluginData('iconSource','Phosphor');return n;}
