    function button(parent,label,x,y,w,target,variant='primary',ic=null){const b=frame(parent,label,x,y,w,48,variant==='primary'?'orange':variant==='soft'?'soft':'white');b.cornerRadius=3;b.setPluginData('uiRole','button');if(variant==='outline'){b.strokes=[paint('orange')];b.strokeWeight=1;}if(ic)icon(b,ic,14,14,20,variant==='primary'?'white':'orange');text(b,label,ic?42:12,14,w-(ic?52:24),mobile&&w<220?12:w<150?12:14,'bold',variant==='primary'?'white':variant==='secondary'?'price':'orange',1);if(target)link(b,target);return b;}
