    for(let i=routes.length-1;i>=0;i--){if(routes[i].node.removed){routes.splice(i,1);continue;}routes[i].target=canonical(routes[i].target);routes[i].overlay=nodes[routes[i].target].getPluginData('overlay')==='1';routes[i].node.setPluginData('routeTarget',routes[i].target);}
